import type { ProductImage } from "@hv/core";
import placeholderProduct from "@hv/ui/illustrations/placeholder-product.svg?url";
import media from "~/lib/media.json";

const MEDIA = media as Record<string, { width: number; height: number; widths: number[] }>;

/** Widths generated by the dashboard at upload (PLAN.md). */
export const IMAGE_WIDTHS = [400, 800, 1200, 2000] as const;

export interface ResolvedImage {
  src: string;
  alt: string;
  width: number;
  height: number;
  /** AVIF then WebP sources for <picture>; empty for placeholders. */
  sources: { type: string; srcSet: string }[];
}

export function isPlaceholder(img: ProductImage): boolean {
  return img.key.startsWith("placeholder/");
}

/**
 * R2 layout: `${IMAGE_BASE}/${key}/${width}.${avif|webp}`.
 * Placeholders resolve to the neutral grey SVG until her photos arrive.
 */
export function resolveImage(img: ProductImage, imageBase: string): ResolvedImage {
  // Design stand-ins for the local sample catalogue: served from /media at the sizes that exist.
  if (img.key.startsWith("standin/")) {
    const slot = img.key.slice("standin/".length);
    const entry = MEDIA[slot];
    if (entry) {
      const set = (ext: string) => entry.widths.map((w) => `/media/${slot}/${w}.${ext} ${w}w`).join(", ");
      return {
        src: `/media/${slot}/${entry.widths[entry.widths.length - 1]}.webp`,
        alt: img.alt,
        width: entry.width,
        height: entry.height,
        sources: [
          { type: "image/avif", srcSet: set("avif") },
          { type: "image/webp", srcSet: set("webp") },
        ],
      };
    }
  }
  if (isPlaceholder(img) || img.key.startsWith("standin/") || !imageBase) {
    return { src: placeholderProduct, alt: img.alt, width: img.width, height: img.height, sources: [] };
  }
  const set = (ext: string) => IMAGE_WIDTHS.map((w) => `${imageBase}/${img.key}/${w}.${ext} ${w}w`).join(", ");
  return {
    src: `${imageBase}/${img.key}/800.webp`,
    alt: img.alt,
    width: img.width,
    height: img.height,
    sources: [
      { type: "image/avif", srcSet: set("avif") },
      { type: "image/webp", srcSet: set("webp") },
    ],
  };
}
